import { test } from "node:test";
import assert from "node:assert/strict";

const BASE = process.env.API_BASE_URL;
const email = () => `qa+${Date.now()}${Math.random().toString(36).slice(2, 6)}@example.com`;
const baseline = () => ({ email: email(), password: "correct-horse-9", plan: "free" });

const cases = [
  { id: "T01", body: baseline(), expected: 201 },
  { id: "T03", body: (({ email, ...rest }) => rest)(baseline()), expected: 400 },
  { id: "T06", body: { ...baseline(), plan: "enterprise" }, expected: 400 },
  { id: "T07", body: { ...baseline(), password: "a".repeat(11) }, expected: 400 },
  { id: "T08", body: { ...baseline(), password: "a".repeat(12) }, expected: 201 },
  { id: "T10", body: { ...baseline(), password: "a".repeat(129) }, expected: 400 }
];

for (const c of cases) {
  test(`${c.id} returns ${c.expected}`, async () => {
    const res = await fetch(`${BASE}/v1/signups`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(c.body)
    });
    assert.equal(res.status, c.expected);
  });
}
